class Solution {
public:
    vector<int> findDuplicates(vector<int>& nums) {
        vector<int> res;
        for (int x : nums) {
            int idx = abs(x) - 1;
            if (nums[idx] < 0) {
                res.push_back(idx + 1);
            } else {
                nums[idx] = -nums[idx];
            }
        }
        return res;
    }
};

class Solution {
    public List<Integer> findDuplicates(int[] nums) {
        List<Integer> res = new ArrayList<>();
        for (int x : nums) {
            int idx = Math.abs(x) - 1;
            if (nums[idx] < 0) {
                res.add(idx + 1);
            } else {
                nums[idx] = -nums[idx];
            }
        }
        return res;
    }
}

var findDuplicates = function(nums) {
    const res = [];
    for (const x of nums) {
        const idx = Math.abs(x) - 1;
        if (nums[idx] < 0) {
            res.push(idx + 1);
        } else {
            nums[idx] = -nums[idx];
        }
    }
    return res;
};
